'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],K=GameKit,E=Haewon,KEY='haewonCase';
let state=E.restore(K.read(KEY)),active=false,paused=false,lastTick=performance.now(),currentMessage=0;
const chapters=['동문 기록','일곱 개의 소원','지워진 학생','사건 당일','마지막 쪽지','남겨야 할 기록','졸업 기록'];
const hints=[
 ['추모관의 일곱 동문은 모두 같은 반이었습니다. 각 기록을 열어보세요.','사망 기록 아래의 마지막 접속 기록을 비교해 보세요.','일곱 기록을 모두 읽으면 소원함이 열립니다. 읽은 기록은 카드 왼쪽에 표시됩니다.'],
 ['추모 기록과 소원 게시물에는 닮은 표현이 남아 있습니다.','행동, 소원, 사망 기록을 함께 비교하세요. 잘못 연결한 행은 확인 후 표시됩니다.','김민재: 침수 / 박소연: 화재 / 이도윤: 승강기 / 최유라: 계단 / 정하린: 무시된 요청 / 오준호: 도주 사고 / 서태훈: 방송실'],
 ['두 댓글을 동시에 만족하는 자리는 하나입니다. 위에서 아래로 줄을 셉니다.','최유라의 바로 뒷줄이면서, 박지우의 바로 왼쪽을 찾아보세요.','위에서 두 번째 줄, 왼쪽에서 네 번째 칸이 가영의 자리입니다.'],
 ['서로 다른 기록의 시각을 대조하세요. 관리자의 경위서도 읽어야 합니다.','선택 목록의 위·아래 버튼으로 순서를 바꿀 수 있습니다. 먼저 18:20 기록을 놓아보세요.','18:20 → 18:34 → 18:41 → 18:43 → 18:47 → 18:49 → 18:50 → 18:51 → 18:56 → 19:08 → 19:23. 관리자 기록 탭의 경위서도 확인하세요.'],
 ['기록보관실의 사진 A와 B에는 당신이 붙여준 제목이 남아 있습니다.','각 제목의 앞 두 글자만 A → B 순서로 이어주세요.','푸른 오후의 “푸른”과 바다로 가는 계단의 “바다”를 이으면 “푸른바다”입니다. 쪽지 두 통을 모두 읽어주세요.'],
 ['사과문의 길이나 표현으로 결말을 평가하지 않습니다. 이후의 행동이 결말을 정합니다.','가영의 기록만 복원할지, 자신의 선택까지 공개할지 결정해야 합니다.','모든 진실 공개: 진정한 졸업 / 가영의 기록만 복원: 불완전한 사과 / 다시 삭제: 반복']
];
function save(){state.stage=E.stage(state);const ok=K.write(KEY,state);$('#saveStatus').textContent=ok?'자동 저장됨':'저장 불가 · 진행 파일로 보관하세요.';}
function objective(){const n=state.stage;if(n===0)return `추모관에서 동문 기록 ${state.read.length}/7 확인하기`;if(n===1)return '행동·소원·사망 기록을 올바르게 연결하기';if(n===2)return '댓글 두 개를 대조해 가영의 원래 자리 찾기';if(n===3){if(!state.timelineSolved)return '화재 당일 기록을 시간순으로 복원하기';return '관리자 기록 탭에서 미전송 경위서 확인하기'}if(n===4)return state.messageSolved?'복구된 쪽지 두 통을 읽고 그날의 선택 확인하기':'사진 제목에 남긴 암호로 쪽지 복구하기';if(n===5)return '가영에게 남길 말과 공개할 기록 결정하기';return '조사 완료 · 복원 기록을 다시 볼 수 있습니다.'}
function sync(){state.stage=E.stage(state);$('#objective').textContent=objective();$('#chapterLabel').textContent=String(Math.min(6,state.stage+1)).padStart(2,'0')+' / '+chapters[state.stage];$$('#progressList li').forEach((li,i)=>{li.classList.toggle('done',i<state.stage);li.classList.toggle('current',i===Math.min(4,state.stage));});$$('.main-nav [data-page]').forEach(b=>{const locked=!E.canOpen(state,b.dataset.page);b.classList.toggle('nav-locked',locked);b.setAttribute('aria-disabled',String(locked))});$('#eighthSeat').classList.toggle('hidden',state.read.length<7);$('#messageCount').textContent=state.stage>=4?String(2-state.messageRead.length):state.stage>=1?'1':'0';$('#messageLock').classList.toggle('hidden',state.messageSolved);$('#messageInbox').classList.toggle('hidden',!state.messageSolved);$('#visitorCount').textContent=state.ending?'1':state.read.length===7?'8':'1';$('.redacted').classList.toggle('reveal',state.timelineSolved);document.body.classList.toggle('past',state.past);$('#todayLabel').textContent=state.past?'2006.10.17':'2026.10.17';renderJournal();renderClock();}
function applyName(){['loginName','oldPlayerName','memoryPlayer1','memoryPlayer2','confessionName','endingPlayer','badName','eighthName','partialName'].forEach(id=>{const el=$('#'+id);if(el)el.textContent=state.name});}
function showPage(id,focus=true){if(!$('#'+id)?.classList.contains('page'))return;if(!E.canOpen(state,id)){K.toast('현재 목표를 완료하면 이 기록을 열람할 수 있습니다.');return}state.page=id;$$('.page').forEach(p=>p.classList.toggle('active-page',p.id===id));$$('[data-page]').forEach(b=>{const on=b.dataset.page===id;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(id==='messages'&&state.messageSolved)renderMessage(currentMessage);if(id==='journal')renderJournal();if(id==='finale')$('#apology').value=state.apology;save();sync();if(focus){$('#mainContent').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}}
function enterGame(name){$$('.error').forEach(el=>el.textContent='');if(name!==undefined)state.name=name.trim().slice(0,12);active=true;paused=false;$('#intro').classList.add('hidden');$('#site').classList.remove('hidden');applyName();renderMemorials();renderWish();renderAlbum();renderTimeline();$('#apology').value=state.apology;$('#investigatorNotes').value=state.notes;sync();showPage(E.canOpen(state,state.page)?state.page:'home',false);save();if(state.read.length===0)$('#ghostMessage').classList.remove('hidden');}
function startNew(){const n=$('#playerName').value.trim();if(!n){$('#introError').textContent='동문 계정에 표시할 이름을 입력해 주세요.';$('#playerName').focus();return}if(state.name){confirmAction('새 기록을 시작할까요?','현재 진행을 초기화하고 새 이름으로 시작합니다.',()=>{state=E.fresh();enterGame(n)});return}enterGame(n)}
function confirmAction(title,copy,action,label='확인'){K.open(title,`<p>${copy}</p><div class="dialog-actions"><button data-close-dialog class="old-button">돌아가기</button><button id="confirmAction" class="submit-btn">${label}</button></div>`);$('#confirmAction').onclick=()=>{K.close();action()};}
function reset(){confirmAction('처음부터 시작할까요?','현재 진행은 초기화됩니다. 보관하려면 일시정지 메뉴에서 진행 파일을 내려받으세요.',()=>{state=E.fresh();save();active=false;$('#site').classList.add('hidden');$('#intro').classList.remove('hidden');$('#resumeBox').classList.add('hidden');$('#playerName').value='';$('#enterBtn').textContent='홈페이지 접속';$('#playerName').focus();},'새로 시작')}
function renderMemorials(){$('#memorialGrid').innerHTML=people.map((p,i)=>`<button class="memorial-card ${state.read.includes(i)?'read':''}" data-person="${i}"><span class="record-number">${String(i+1).padStart(2,'0')}</span><div><b>${p.name}</b><small>2006년 2학년 4반 · ${state.read.includes(i)?'확인함':'미확인'}</small></div><time>${p.year}</time></button>`).join('')}
function openPerson(i){const p=people[i],lastSeen=new Date(p.year.replaceAll('.','-')+'T00:00:00Z');lastSeen.setUTCDate(lastSeen.getUTCDate()-1);const lastDate=lastSeen.toISOString().slice(0,10).replaceAll('-','.');if(!state.read.includes(i))state.read.push(i);save();renderMemorials();sync();K.open('동문 추모 기록 '+String(i+1).padStart(2,'0'),`<p class="doc-meta">2006년 2학년 4반 / ${p.year}</p><h3>${p.name}</h3><p class="death">${p.death}</p><p><b>마지막 홈페이지 접속</b><br>${lastDate} · 사망 전날 계정 접속 확인</p><p class="fragment">복원된 게시물 제목: 소원을 이루었습니다.<br>작성 계정: ${p.name}</p>${state.stage>=1?`<p><b>복구된 소원</b><br>“${p.wish}”</p>`:''}<p class="fine">동문 기록 ${state.read.length}/7 확인</p>${state.read.length===7?'<button id="goWish" class="submit-btn">복원된 소원함으로</button>':'<button data-close-dialog class="old-button">기록 닫기</button>'}`);if($('#goWish'))$('#goWish').onclick=()=>{K.close();showPage('wish')};}
function renderWish(){$('#wishForm').innerHTML=people.map((p,i)=>`<label class="wish-row"><b>${String(i+1).padStart(2,'0')} ${p.name}</b><span>${p.act}<small>“${p.wish}”</small></span><select data-wish="${i}" aria-label="${p.name}의 사망 기록" ${state.wishSolved?'disabled':''}>${deathOptions.map(o=>`<option value="${o[0]}" ${state.wishChoices[i]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></label>`).join('');$('#wishSubmit').textContent=state.wishSolved?'복원된 졸업앨범 열기':'연결 기록 확인';}
function checkWish(){if(state.wishSolved){showPage('album');return}const values=$$('[data-wish]').map(x=>x.value),checks=E.checkWishes(values);$$('[data-wish]').forEach((x,i)=>{x.setAttribute('aria-invalid',String(!checks[i]));x.closest('.wish-row').classList.toggle('incorrect',!checks[i])});state.wishChoices=values;save();if(!checks.every(Boolean)){$('#wishError').textContent=values.some(x=>!x)?'아직 선택하지 않은 사망 기록이 있습니다. 표시된 행을 확인하세요.':`기억과 다른 연결이 ${checks.filter(x=>!x).length}개 있습니다. 표시된 행의 소원과 추모 기록을 비교하세요.`;return}state.wishSolved=true;save();renderWish();sync();K.open('일곱 개의 소원',`<p>그들은 책임을 지우고 싶었습니다. 관리자는 실제로 기록을 지웠습니다.</p><p>그러나 사라진 기록은 매년 돌아왔고, 소원을 등록한 순서대로 일곱 계정의 주인이 세상을 떠났습니다.</p><p class="fragment">삭제된 학생: 윤가영<br>연결된 자료: 2006년 2학년 4반 학급기록</p><button id="goAlbum" class="submit-btn">학급기록 확인</button>`);$('#goAlbum').onclick=()=>{K.close();showPage('album')};}
function renderAlbum(){const names=['김민재','박소연','','최유라','정하린','오준호','서태훈','김수현',state.albumSolved?'윤가영':'','박지우','한예린',state.name,'임다은','강재호','문세진','','송지호','백서진','차예원','남도현','고은채','','류시은','안지민','권민호'];$('#classGrid').innerHTML=names.map((n,i)=>`<button class="student-record ${!n?'missing':''} ${i===8&&state.albumSolved?'restored':''}" data-seat="${i+1}" aria-label="${Math.floor(i/5)+1}줄 ${i%5+1}번째, ${K.escape(n||'사진 유실')}" ${state.albumSolved?'disabled':''}><small>${String(i+1).padStart(2,'0')}</small><b>${K.escape(n||'기록 유실')}</b></button>`).join('');if(state.albumSolved)$('#albumError').innerHTML='윤가영의 학급기록이 복원되었습니다. <button class="old-button" data-next-archive>기록보관실로</button>';}
function selectSeat(i){if(state.albumSolved)return;if(i!==9){$('#albumError').textContent='두 댓글과 맞지 않는 자리입니다. 같은 세로줄의 앞사람과 바로 오른쪽 사람을 함께 확인하세요.';return}state.albumSolved=true;save();renderAlbum();sync();K.open('삭제된 학생 · 윤가영',`<p class="doc-meta">2006.05.12 / 홈페이지 사진 댓글 복원</p><h3>“사진 제목, 네가 지어줄래?”</h3><p>전학 온 가영의 첫 사진에 댓글을 단 사람은 ${K.escape(state.name)}이었습니다.</p><p>그 뒤로 두 사람은 옥상 계단에서 우유를 나눠 마시고, 방송부 창고에서 같은 노래를 들었습니다. 시험이 끝나면 함께 바다에 가기로 했습니다.</p><blockquote>“졸업할 때까지 지금처럼 지내게 해주세요.”</blockquote><p>이 쪽지는 둘이 창고에 숨긴 개인적인 약속이었습니다. 관리자의 소원함에 등록한 소원은 아니었습니다.</p><button id="goArchive" class="submit-btn">둘이 남긴 기록 확인</button>`);$('#goArchive').onclick=()=>{K.close();showPage('archive')};}
function renderTimeline(){const order=[6,2,10,0,8,4,1,9,5,3,7];$('#timelineCards').innerHTML=order.map(i=>{const t=timeline[i],selected=state.timelineOrder.includes(t.id);return `<button class="timeline-card ${selected?'selected':''}" data-event="${t.id}" aria-pressed="${selected}" ${state.timelineSolved?'disabled':''}><small>${t.source}</small><span>${t.time}</span>${t.text}</button>`}).join('');renderOrder();$('#timelineCheck').textContent=state.timelineSolved?'시간 기록 복원 완료':'시간 순서 확인';$('#timelineCheck').disabled=state.timelineSolved;$('#timelineReset').disabled=state.timelineSolved;}
function renderOrder(){$('#timelineOrder').innerHTML=state.timelineOrder.length?state.timelineOrder.map((id,i)=>{const t=timeline.find(x=>x.id===id);return `<li><div><time>${t.time}</time> ${t.text}</div>${!state.timelineSolved?`<div class="order-tools"><button data-move="${i}" data-dir="-1" aria-label="${t.time} 기록 위로" ${i===0?'disabled':''}>위</button><button data-move="${i}" data-dir="1" aria-label="${t.time} 기록 아래로" ${i===state.timelineOrder.length-1?'disabled':''}>아래</button><button data-remove="${id}" aria-label="${t.time} 기록 선택 취소">빼기</button></div>`:''}</li>`}).join(''):'<li>왼쪽 기록을 누르면 이곳에 추가됩니다.</li>';}
function checkTimeline(){if(!E.checkTimeline(state.timelineOrder)){$('#timelineError').textContent=state.timelineOrder.length<timeline.length?`기록 ${state.timelineOrder.length}/11 선택. 빠진 기록을 추가해 주세요.`:'일부 기록이 시간순으로 놓이지 않았습니다. 위·아래 버튼으로 수정할 수 있습니다.';return}state.timelineSolved=true;save();renderTimeline();sync();$('#timelineError').textContent='18:47의 구조 요청 이후에도 시간이 있었습니다. 경보는 19:08에야 울렸습니다.';K.toast(state.teacherRead?'삭제된 쪽지함이 복원되었습니다.':'시간 기록 복원 완료 · 관리자 기록도 확인해 주세요.');if(state.teacherRead)showPage('messages');}
function readTeacher(){if(state.stage<3)return;if(!state.teacherRead){state.teacherRead=true;save();sync();K.toast('한명석의 경위서를 단서 수첩에 기록했습니다.')}if(state.timelineSolved)$('#teacherPane').insertAdjacentHTML('beforeend',$('#teacherNext')?'':'<button id="teacherNext" class="submit-btn">복원된 쪽지함 확인</button>');if($('#teacherNext'))$('#teacherNext').onclick=()=>showPage('messages');}
function renderMessage(i){if(!state.messageSolved)return;currentMessage=i;if(!state.messageRead.includes(i))state.messageRead.push(i);save();sync();$$('[data-message]').forEach(b=>{b.classList.toggle('selected',+b.dataset.message===i);b.setAttribute('aria-pressed',String(+b.dataset.message===i))});const first=i===0;$('#messageBody').innerHTML=`<p class="msg-meta">윤가영 · 2006.10.17 ${first?'18:47':'18:56'}</p><h3>${first?'방송실에 갇혔어':'다른 사람은 몰라도'}</h3><p>${first?'방송실에 갇혔어.<br>연기가 나. 선생님을 불러줘.':'다른 사람은 몰라도<br><strong>너는 올 줄 알았어.</strong>'}</p><div class="read-log">수신자: <b>${K.escape(state.name)}</b><br>${first?'읽은 시각 18:49 · 삭제한 시각 18:51':'당시 상태: 읽지 않음 · 현재 복구됨'}</div><p>${first?'기록 속 이름을 잘못 읽은 것이 아닙니다. 당신은 그날 쪽지를 읽었습니다.':'가영은 마지막 순간까지 당신의 대답을 기다렸습니다.'}</p>${state.messageRead.length===2?'<button id="faceTruthBtn" class="submit-btn">그날의 일을 인정한다</button>':'<button id="nextMessage" class="old-button">다음 쪽지 읽기</button>'}`;if($('#nextMessage'))$('#nextMessage').onclick=()=>renderMessage(1);if($('#faceTruthBtn'))$('#faceTruthBtn').onclick=()=>{if(state.ending){showEnding();return}state.truthFaced=true;save();sync();showPage('finale')};}
function renderJournal(){const entries=state.read.map(i=>({title:people[i].name+' · 추모 기록',body:people[i].year+' / '+people[i].death,page:'memorial'}));if(state.wishSolved)entries.push({title:'일곱 개의 소원',body:'소원은 등록 순서대로 대가가 돌아왔다. 관리자는 불리한 기록을 삭제했다.',page:'wish'});if(state.albumSolved)entries.push({title:'가영의 자리와 약속',body:'2줄 4번째. 사진의 제목을 함께 짓고 졸업 후 바다에 가기로 했다. 창고의 쪽지는 둘만의 약속이었다.',page:'album'});if(state.timelineSolved)entries.push({title:'화재 타임라인',body:'18:47 요청 → 18:49 읽음 → 18:51 삭제 → 18:56 마지막 쪽지 → 19:08 경보',page:'archive'});if(state.teacherRead)entries.push({title:'한명석의 미전송 경위서',body:'시험 답안지 사진, 구조 요청, 접속 기록을 관리자 권한으로 지웠다.',page:'archive'});if(state.messageSolved)entries.push({title:'삭제된 쪽지의 수신자',body:'수신자는 '+state.name+'. 가영의 요청을 읽고 삭제했다.',page:'messages'});$('#journalList').innerHTML=entries.length?entries.map(x=>`<button class="journal-item" data-journal-page="${x.page}"><b>${K.escape(x.title)}</b><p>${K.escape(x.body)}</p><small>원본 기록 열기</small></button>`).join(''):'<p class="notice blue">추모관에서 첫 기록을 열어보세요. 발견한 단서가 이곳에 모입니다.</p>';}
function endingChoice(choice){const texts={truth:['모든 진실을 공개할까요?','학교의 은폐, 일곱 명의 행동, 자신의 방관을 게임 속 동문 게시판에 함께 남깁니다.'],partial:['가영의 기록만 복원할까요?','가영의 명예는 회복됩니다. 자신의 방관 기록은 공개하지 않습니다.'],repeat:['모든 기록을 다시 삭제할까요?','가영의 이름과 마지막 쪽지까지 다시 지웁니다. 이 선택으로 이번 조사의 결말이 결정됩니다.']};confirmAction(texts[choice][0],texts[choice][1],()=>{if(!E.chooseEnding(state,choice)){K.toast('쪽지 두 통을 먼저 읽고 마지막 선택으로 돌아와 주세요.');return}state.apology=$('#apology').value;save();sync();showEnding()},'이 선택으로 마무리');}
function showEnding(){active=false;$('#ghostMessage').classList.add('hidden');showPage({truth:'ending',partial:'partialEnding',repeat:'badEnding'}[state.ending]||'finale');}
function hint(level){const index=Math.min(5,state.stage),n=Math.min(2,level??state.hintLevels[index]??0);state.hintLevels[index]=n;state.hintUses++;save();K.open('기록 복원 도움말 · '+(n+1)+'/3',`<p class="hint-objective">${objective()}</p><p>${hints[index][n]}</p><div class="dialog-actions"><button data-close-dialog class="old-button">계속 조사</button>${n<2?'<button id="moreHint" class="submit-btn">'+(n===1?'정답 확인':'한 단계 더 보기')+'</button>':''}</div>`);if($('#moreHint'))$('#moreHint').onclick=()=>hint(n+1);}
function pause(){paused=true;save();K.open('조사 일시정지','<p>진행 상황을 저장했습니다. 기록 삭제 타이머도 잠시 멈춥니다.</p><div class="menu-stack"><button data-close-dialog class="submit-btn">조사 계속</button><button id="exportProgress" class="old-button">진행 파일 내려받기</button><button id="loadProgress" class="old-button">진행 파일 불러오기</button><button id="resetProgress" class="old-button">처음부터</button>'+ (state.ending?'<button id="endingReturn" class="old-button">결말 다시 보기</button>':'')+'</div><p class="intro-help">파일을 옮기거나 다른 브라우저에서 이어 하려면 진행 파일을 함께 보관하세요.</p>');$('#exportProgress').onclick=()=>K.export(KEY,state);$('#loadProgress').onclick=()=>$('#importFile').click();$('#resetProgress').onclick=reset;if($('#endingReturn'))$('#endingReturn').onclick=()=>{K.close();showEnding()};}
function renderClock(){const remain=Math.max(0,2700-Math.floor(state.elapsed));$('#timer').textContent=state.ending?'기록 종료':`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;}
const notices={
 '폐교에 따른 홈페이지 자료 삭제 안내':'학교는 2026년 폐교를 앞두고 있습니다. 동문 여러분의 사진과 게시물은 백업 종료 이후 삭제될 예정입니다. 추모관과 학급기록을 마지막으로 확인해 주십시오.',
 '동문 추모관 임시 개방 안내':'최근 동문 일곱 명의 추모 기록이 한곳에 모였습니다. 모두 2006년 2학년 4반 소속이었습니다. 마지막으로 접속한 계정 기록도 함께 보관합니다.',
 '구관 철거 작업으로 인한 출입 통제':'본교 구관의 지상 부분은 철거되었습니다. 지하 방송실 구역은 현장 조사로 철거가 보류되어 출입이 통제됩니다.',
 '2006년 10월 17일 축제 취소 안내':'구관 방송실 화재로 학교 축제가 취소되었습니다. 당시 학교는 학생의 장비 조작 실수를 원인으로 발표했습니다. 첨부된 사고 조사서는 삭제되어 있습니다.'
};
$('#enterBtn').onclick=startNew;$('#playerName').onkeydown=e=>{if(e.key==='Enter')startNew()};$('#resumeBtn').onclick=()=>enterGame();$('#introImport').onclick=()=>$('#importFile').click();$('#hintBtn').onclick=()=>hint();$('#journalBtn').onclick=()=>showPage('journal');$('#pauseBtn').onclick=pause;
$('#ghostOpen').onclick=()=>{$('#ghostMessage').classList.add('hidden');K.open('보낸 사람: 윤가영','<p class="doc-meta">읽지 않은 쪽지가 남아 있어</p><blockquote>이번에는 지우지 마.</blockquote><p>쪽지의 첨부 링크는 동문 추모관으로 이어집니다.</p><button id="ghostNext" class="submit-btn">추모관 확인</button>');$('#ghostNext').onclick=()=>{K.close();showPage('memorial')};};
$$('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$$('[data-notice]').forEach(b=>b.onclick=e=>{e.preventDefault();K.open(b.dataset.notice,`<p>${notices[b.dataset.notice]}</p><button data-close-dialog class="old-button">닫기</button>`)});
$('#memorialGrid').onclick=e=>{const b=e.target.closest('[data-person]');if(b)openPerson(+b.dataset.person)};$('#wishSubmit').onclick=checkWish;$('#wishForm').onsubmit=e=>{e.preventDefault();checkWish()};$('#wishForm').onchange=e=>{if(!e.target.matches('[data-wish]'))return;state.wishChoices[+e.target.dataset.wish]=e.target.value;e.target.removeAttribute('aria-invalid');e.target.closest('.wish-row').classList.remove('incorrect');save()};
$('#classGrid').onclick=e=>{const b=e.target.closest('[data-seat]');if(b)selectSeat(+b.dataset.seat)};$('#albumError').onclick=e=>{if(e.target.closest('[data-next-archive]'))showPage('archive')};
$('#timelineCards').onclick=e=>{const b=e.target.closest('[data-event]');if(!b||state.timelineSolved)return;const id=b.dataset.event;state.timelineOrder=state.timelineOrder.includes(id)?state.timelineOrder.filter(x=>x!==id):[...state.timelineOrder,id];save();renderTimeline()};$('#timelineOrder').onclick=e=>{if(state.timelineSolved)return;const move=e.target.closest('[data-move]'),remove=e.target.closest('[data-remove]');if(move){const i=+move.dataset.move,j=i+(+move.dataset.dir);if(j>=0&&j<state.timelineOrder.length)[state.timelineOrder[i],state.timelineOrder[j]]=[state.timelineOrder[j],state.timelineOrder[i]]}if(remove)state.timelineOrder=state.timelineOrder.filter(x=>x!==remove.dataset.remove);save();renderTimeline()};$('#timelineReset').onclick=()=>{if(state.timelineSolved)return;state.timelineOrder=[];save();renderTimeline();$('#timelineError').textContent=''};$('#timelineCheck').onclick=checkTimeline;
$$('.archive-tab').forEach(b=>b.onclick=()=>{$$('.archive-tab').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$$('.archive-pane').forEach(x=>x.classList.toggle('active-archive',x.id===b.dataset.archive));if(b.dataset.archive==='teacherPane')readTeacher()});
$('#messageForm').onsubmit=e=>{e.preventDefault();if($('#messagePassword').value.normalize('NFKC').replace(/\s/g,'')!=='푸른바다'){$('#messageError').textContent='아직 기억이 맞지 않습니다. 사진 A와 B의 앞 두 글자를 순서대로 이어주세요.';return}state.messageSolved=true;save();sync();renderMessage(0)};$$('[data-message]').forEach(b=>b.onclick=()=>renderMessage(+b.dataset.message));$('#apology').oninput=e=>{state.apology=e.target.value;save()};$('#publishTruth').onclick=()=>endingChoice('truth');$('#restoreOnly').onclick=()=>endingChoice('partial');$('#deleteAgain').onclick=()=>endingChoice('repeat');['replayBtn','badReplayBtn','partialReplay'].forEach(id=>$('#'+id).onclick=reset);['reviewEnding','partialReview'].forEach(id=>$('#'+id).onclick=()=>showPage('journal'));
$('#journalList').onclick=e=>{const b=e.target.closest('[data-journal-page]');if(b)showPage(b.dataset.journalPage)};$('#investigatorNotes').oninput=e=>{state.notes=e.target.value;save()};
$('#importFile').onchange=e=>{const file=e.target.files[0];e.target.value='';if(!file)return;confirmAction('진행 파일을 불러올까요?','현재 진행을 선택한 파일의 기록으로 바꿉니다.',()=>K.import(file,KEY,raw=>{state=E.restore(raw);save();if(state.name){enterGame();K.toast('진행 기록을 불러왔습니다.')}else K.toast('시작 전 기록입니다. 동문 이름을 입력해 주세요.')}),'불러오기')};
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open)paused=false;lastTick=performance.now()});
setInterval(()=>{const now=performance.now(),delta=Math.min(2,(now-lastTick)/1000);lastTick=now;if(active&&!paused&&!document.hidden&&!state.ending){state.elapsed+=delta;if(state.elapsed>=2700&&!state.past){state.past=true;save();sync();K.toast('기록 삭제 실패 · 2006년 백업으로 전환되었습니다. 조사는 계속할 수 있습니다.')}renderClock();if(Math.floor(state.elapsed)%5===0)save()}},1000);document.addEventListener('visibilitychange',()=>{save();lastTick=performance.now()});window.addEventListener('pagehide',save);
if(state.name){$('#resumeBox').classList.remove('hidden');$('#resumeText').textContent=`${state.name} · ${chapters[state.stage]} · 동문 기록 ${state.read.length}/7`;$('#enterBtn').textContent='새 이름으로 시작';}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_case_progress',description:'복원된 해원고 사건 기록의 진행 상태를 확인합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>({content:[{type:'text',text:JSON.stringify({stage:state.stage,read:state.read.length,objective:objective(),ending:state.ending})}]})});document.modelContext.registerTool({name:'reset_case_progress',description:'사용자 확인 후 이 기기의 진행 기록을 초기화합니다.',inputSchema:{type:'object',properties:{confirm:{type:'boolean'}},required:['confirm'],additionalProperties:false},execute:async input=>{if(input?.confirm!==true)throw Error('명시적 확인이 필요합니다.');reset();return{content:[{type:'text',text:'초기화 확인창을 열었습니다.'}]}}})}catch{}}
